    cols = [2, 7, 12, 17]
    rows = [8, 13, 18, 23]

    def pattern(r, c):
        return tuple(tuple(grid[rr][cc] != 8 for cc in range(c, c + 3))
                     for rr in range(r, r + 3))

    keys = [pattern(1, c) for c in cols]
    matches = [[pattern(r, c) in keys for c in cols] for r in rows]
    complete_rows = [i for i, m in enumerate(matches) if all(m)]
    complete_cols = [j for j in range(4)
                     if all(matches[i][j] for i in range(4))]

    def fill_block(r, c):
        for rr in range(r - 1, r + 4):
            for cc in range(c - 1, c + 4):
                if out[rr][cc] == 8:
                    out[rr][cc] = 3

    if complete_rows:
        for r in range(5):
            for c in range(len(grid[0])):
                if out[r][c] == 8:
                    out[r][c] = 3
        i = complete_rows[0]
        for rr in range(rows[i] - 1, rows[i] + 4):
            for cc in range(1, 21):
                if out[rr][cc] == 8:
                    out[rr][cc] = 3
        for rr in range(28, len(grid)):
            for cc in range(len(grid[0])):
                if out[rr][cc] == 8:
                    out[rr][cc] = 3
    elif complete_cols:
        j = complete_cols[0]
        for r in range(5):
            for c in range(len(grid[0])):
                if out[r][c] == 8:
                    out[r][c] = 3
        for rr in range(7, 27):
            for cc in range(cols[j] - 1, cols[j] + 4):
                if out[rr][cc] == 8:
                    out[rr][cc] = 3
        for rr in range(28, len(grid)):
            for cc in range(len(grid[0])):
                if out[rr][cc] == 8:
                    out[rr][cc] = 3
    else:
        for i in range(4):
            for j in range(4):
                if matches[i][j]:
                    fill_block(rows[i], cols[j])
        common = set(c for key in keys for row in key for c in row)
        common.discard(False)
        fill = next((grid[1][c] for c in cols
                     if grid[1][c] != 8 and grid[1][c] not in (6, 8)), 2)
        # The individual-match case uses the query's repeated color.
        counts = {}
        for c in cols:
            for rr in range(1, 4):
                for cc in range(c, c + 3):
                    v = grid[rr][cc]
                    if v != 8:
                        counts[v] = counts.get(v, 0) + 1
        fill = max(counts, key=counts.get)
        for rr in range(28, len(grid)):
            for cc in range(len(grid[0])):
                if out[rr][cc] == 8:
                    out[rr][cc] = fill
    return out
